package com.asr.asr_banking_simulator.dto;

/**
 * QueryExplainPlanDto — Cost-Based Optimizer (CBO) EXPLAIN ANALYZE Report
 * ============================================================================
 * Educational Purpose (DBMS Mini-Project — STAGE 14):
 * Encapsulates the Volcano Iterator Execution Tree, actual vs estimated rows,
 * and CPU timing generated by MySQL's modern EXPLAIN ANALYZE engine.
 * ============================================================================
 */
public class QueryExplainPlanDto {

    private String queryType;
    private String sqlStatement;
    private String explainPlanTree;
    private String optimizationNotes;

    public QueryExplainPlanDto() {
    }

    public QueryExplainPlanDto(String queryType, String sqlStatement, String explainPlanTree, String optimizationNotes) {
        this.queryType = queryType;
        this.sqlStatement = sqlStatement;
        this.explainPlanTree = explainPlanTree;
        this.optimizationNotes = optimizationNotes;
    }

    public String getQueryType() {
        return queryType;
    }

    public void setQueryType(String queryType) {
        this.queryType = queryType;
    }

    public String getSqlStatement() {
        return sqlStatement;
    }

    public void setSqlStatement(String sqlStatement) {
        this.sqlStatement = sqlStatement;
    }

    public String getExplainPlanTree() {
        return explainPlanTree;
    }

    public void setExplainPlanTree(String explainPlanTree) {
        this.explainPlanTree = explainPlanTree;
    }

    public String getOptimizationNotes() {
        return optimizationNotes;
    }

    public void setOptimizationNotes(String optimizationNotes) {
        this.optimizationNotes = optimizationNotes;
    }
}
